#nullable enable // autogenerated  

using MVZ2Logic.Blueprints;
using MVZ2Logic.Games;
using PVZEngine;
using PVZEngine.Level;
using PVZEngine.Definitions;
using PVZEngine.SeedPacks;

namespace MVZ2Logic.Seeds
{
    public class OptionSeed : SeedDefinition
    {
        // 新增 rechargeID 参数：为 null 时表示无冷却（保持旧行为）  
        public OptionSeed(string nsp, string name, int cost, NamespaceID? rechargeID = null) : base(nsp, name)
        {
            SetProperty(LogicSeedProps.SEED_TYPE, SeedTypes.OPTION);
            SetProperty(LogicSeedProps.SEED_OPTION_ID, new NamespaceID(nsp, name));
            SetProperty(EngineSeedProps.COST, (float)cost);
            // 与 EntitySeed 一致：配置了 recharge 就写入充能ID，引擎据此产生冷却  
            SetProperty(EngineSeedProps.RECHARGE_ID, rechargeID);
        }
        public override void Update(SeedPack seedPack, float rechargeSpeed)
        {
            base.Update(seedPack, rechargeSpeed);
            var optionID = seedPack.Definition.GetSeedOptionID();
            if (optionID == null)
                return;
            var optionDef = seedPack.Level.Content.GetSeedOptionDefinition(optionID);
            if (optionDef == null)
                return;
            optionDef.Update(seedPack, rechargeSpeed);
        }
    }
}
